package com.example.academic.evaluation;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/academic/classes") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','TEACHER')") public class EvaluationContextController {private final EvaluationContextService service;@GetMapping("/{id}/evaluation-context") public EvaluationContextService.Context get(@PathVariable Long id,@RequestParam(defaultValue="false") boolean includeAttendance){return service.get(id,includeAttendance);}}